components.css:
.ds-card { font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; max-width: 600px; }
.ds-card-title { margin: 0 0 12px 0; color: #0f172a; font-size: 1rem; font-weight: 700; line-height: 1.3; }
.ds-card-body { margin: 0; color: #475569; font-size: 0.9rem; }

.ds-chart-card { max-width: 100%; }
.ds-chart { display: block; width: 100%; height: auto; }
.ds-legend { display: flex; gap: 16px; margin-top: 12px; font-family: system-ui, sans-serif; font-size: 0.75rem; font-weight: 500; color: #64748b; }
.ds-legend-item { display: inline-flex; align-items: center; gap: 6px; }
.ds-legend-dot { width: 10px; height: 10px; border-radius: 2px; display: inline-block; }
.ds-legend-dot-gas { background: #1e40af; }
.ds-legend-dot-diesel { background: #166534; }

.ds-table { width: 100%; border-collapse: collapse; font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif; font-size: 0.9rem; text-align: left; }
.ds-tr { border-bottom: 1px solid #f1f5f9; }
.ds-th { padding: 8px 10px; background: #f8fafc; color: #64748b; font-size: 0.75rem; font-weight: 500; border-bottom: 2px solid #e2e8f0; }
.ds-td { padding: 10px; color: #475569; font-weight: 500; }
.ds-td-value { font-weight: 700; }
.ds-td-gas { color: #1e40af; }
.ds-td-diesel { color: #166534; }

.ds-td { padding: 10px; font-family: system-ui, sans-serif; font-size: 0.9rem; }
.ds-td-value { font-weight: 700; }
.ds-td-gas { color: #1e40af; }

.ds-td { padding: 10px; font-family: system-ui, sans-serif; font-size: 0.9rem; }
.ds-td-value { font-weight: 700; }
.ds-td-diesel { color: #166534; }
